declarations.code:
template <class T>

concept default_initializable = std::constructible_from<T> && requires { T{}; } &&

    /* T t; is well-formed, see below */;

examples.code:
#include <concepts>
#include <functional>
#include <cassert>
#include <iostream>

int main() {
    // The compiler verifies this requirement before the program runs.
    static_assert(std::default_initializable<int>);
    std::cout << "Checks passed\n";
}
